def transform(grid):
    h, w = len(grid), len(grid[0])

    # The panels are separated by a completely blank column.
    left_w = next((c for c in range(w) if all(grid[r][c] == 0 for r in range(h))), w)
    left = [row[:left_w] for row in grid]

    # The frame color is the most common nonzero color in the left panel.
    counts = {}
    for row in left:
        for value in row:
            if value:
                counts[value] = counts.get(value, 0) + 1
    frame = max(counts, key=counts.get)

    # Record the normalized shape of each colored object in the right panel.
    objects = {}
    seen = set()
    for r in range(h):
        for c in range(left_w + 1, w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and left_w + 1 <= nc < w
                            and (nr, nc) not in seen and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            minr = min(rr for rr, cc in cells)
            minc = min(cc for rr, cc in cells)
            shape = frozenset((rr - minr, cc - minc) for rr, cc in cells)
            objects[shape] = color

    out = [row[:] for row in left]
    # Full frame-color rows divide the left panel into separate slots.
    separators = [r for r in range(h) if all(v == frame for v in left[r])]
    start = 0
    for end in separators + [h]:
        if start < end:
            holes = [(r, c) for r in range(start, end)
                     for c in range(left_w) if left[r][c] == 0]
            if holes:
                minr = min(r for r, c in holes)
                minc = min(c for r, c in holes)
                shape = frozenset((r - minr, c - minc) for r, c in holes)
                color = objects.get(shape)
                if color is not None:
                    for r, c in holes:
                        out[r][c] = color
        start = end + 1

    return out
